from rdkit import Chem
import math

lig = Chem.SDMolSupplier('/workspace/reference.sdf', removeHs=False)[0]
conf = lig.GetConformer()

# load pocket atoms
atoms=[]
with open('/workspace/complex.pdb') as f:
    for line in f:
        if line.startswith('ATOM'):
            name=line[12:16].strip(); resn=line[17:20].strip(); chain=line[21].strip(); resi=int(line[22:26])
            x=float(line[30:38]); y=float(line[38:46]); z=float(line[46:54])
            elem=(line[76:78].strip() or name[0]).strip()
            atoms.append((name,resn,chain,resi,x,y,z,elem))

pocket={( 'A',i) for i in [22,23,31,44,45,46,57,58,59,60,61,62,63,65,74,76,87,88,89,90,91,92,93,94,95,96,97,100,145,146,156,157,158]}
sel=[a for a in atoms if (a[2],a[3]) in pocket]

# potential H-bond distances between ligand hetero/NH hydrogens and protein hetero atoms
for i,atm in enumerate(lig.GetAtoms()):
    sym=atm.GetSymbol()
    pos=conf.GetAtomPosition(i)
    if sym in ['N','O','F']:
        close=[]
        for a in sel:
            if a[7] in ['N','O','S']:
                dx=pos.x-a[4]; dy=pos.y-a[5]; dz=pos.z-a[6]
                d=(dx*dx+dy*dy+dz*dz)**0.5
                if d<4.0:
                    close.append((round(d,2), a[0], a[1], a[2], a[3], a[7]))
        print('Lig atom', i, sym, 'close polar contacts', sorted(close)[:10])

# hydrophobic close contacts <4A for key substituent atoms
for i in [0,4,17,18,19]:
    atm=lig.GetAtomWithIdx(i)
    pos=conf.GetAtomPosition(i)
    close=[]
    for a in sel:
        if a[7] != 'H':
            dx=pos.x-a[4]; dy=pos.y-a[5]; dz=pos.z-a[6]
            d=(dx*dx+dy*dy+dz*dz)**0.5
            if d<4.2:
                close.append((round(d,2), a[0], a[1], a[3], a[7]))
    print('Lig atom', i, atm.GetSymbol(), 'contacts', sorted(close)[:15])

